          const Pi = (q, a) => [S(a) * q.rx * 0.97, q.y, C(a) * q.rz * 0.97 - 0.01];
          b.quad(Pi(A, a1), Pi(A, a0), Pi(B, a0), Pi(B, a1), lining, null, [V3.mul(nr(a1), -1), V3.mul(nr(a0), -1), V3.mul(nr(a0), -1), V3.mul(nr(a1), -1)]);
