    b.quad([-0.065, 0.14, 0.198], [0.065, 0.14, 0.198], [0.052, 0.285, 0.132], [-0.052, 0.285, 0.132], COL_R.undershirt);
    boxAt(b, [-0.078, 0.24, 0.145], [0.048, 0.095, 0.025], COL_R.shirtCollar, M4.rotZ(0.32));
