    ctx.strokeStyle = '#ff3868';
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + R * 0.45, cy - R * 0.32);
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx - R * 0.18, cy - R * 0.64);
    ctx.stroke();
