    ctx.strokeStyle = 'rgba(220,235,255,0.28)';
    ctx.lineWidth = 3;
    ctx.strokeRect(14, 14, w - 28, h - 28);
    ctx.fillStyle = 'rgba(255,110,150,0.45)';
    ctx.font = 'bold 34px Georgia, serif';
    ctx.fillText('WHO AM I ?', 54, 78);
    ctx.strokeStyle = 'rgba(255,80,120,0.5)';
    ctx.lineWidth = 3;
    ctx.beginPath();
