      rg.addColorStop(0, kind === 'intro' ? 'rgba(120,160,255,0.22)' : 'rgba(255,60,100,0.25)');
      rg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = rg;
