    r.draw(V.mEyePatch, m.head, { texture: V.eyes[pose.eyes || 'open'] || V.eyes.open });
    r.draw(V.mMouthPatch, m.head, { texture: V.mouths[pose.mouth || 'smile'] || V.mouths.smile });
    r.draw(V.mHair, m.head);

