      partialLoft(b, tails, 1.25, PI * 2 - 1.25, 14);
      partialLoft(b, tails.map(r => ring(r.y, r.rx - 0.005, r.rz - 0.005, 0, COL.coatLining)), 1.25, PI * 2 - 1.25, 14);
      [-1, 1].forEach(s => ellAt(b, [s * 0.13, 0.135, -0.005], 0.055, 0.04, 0.06, COL.coat, 10, 6));
