    r.draw(V.chest, s.chest, cloth);
    r.draw(V.neckUnit, s.neckCyl, skin);
    r.draw(V.head, s.head, skin);

    const fTex = T['face_' + (o.face || 'shut')] || T.face_shut;
    r.draw(V.face, s.head, { texture: fTex });
