    r.draw(V.upperR, s.upperR, cloth);
    r.draw(V.foreL, s.foreL, skin);
    r.draw(V.foreR, s.foreR, cloth);
    r.draw(V.handL, s.handL, skin);
    r.draw(V.handR, s.handR, cloth);

