    ctx.fillStyle = '#f2f2f2';
    ctx.font = '17px Arial, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Вы мертвы', w / 2, h / 2 + 1);
