    b.at(0, 0.62, 0.06, h => h.box(0.22, 0.12, 0.04, trim, { base: true }));
    b.pop();
    [-1, 1].forEach(s => cube(b, s * 0.3, 0.6, 0.02, 0.06, 0.03, 0.3, 0x1a1a1c));
    cyl(b, 0, 0.12, 0, 0.03, 0.03, 0.28, 6, 0x2a2a2e);
