      hair: { style: 'short', col: 0x9a5a34, hi: 0xc07a48, dk: 0x6a3a20 },
      shirt: 0x6e7076, robe: { col: 0x141416, hi: 0x212125, lining: 0x2a2a2e }, scarf: [0x5e1420, 0xd6a63a],
