      hair: { style: 'short', col: 0x2c2018, hi: 0x44342a, dk: 0x1c140e },
      shirt: 0xe8e6e0, tie: [0x8c1a22, 0xc89a34], robe: { col: 0x161618, hi: 0x232327, lining: 0xa81e26 },
      pants: 0x1c1c20, shoe: 0x101012
