      edge.addColorStop(0.22, rgba(0x7a4a3a, 0));
      edge.addColorStop(0.78, rgba(0x7a4a3a, 0));
      edge.addColorStop(1, rgba(volde ? 0x3a4046 : 0x7a4a3a, 0.25));
      ctx.fillStyle = edge;
