      const browCol = { heavy: 0x2a1c14, scout: 0x2a1c12, soldier: 0x2a1e16, demo: 0x1a1412, engineer: 0x4a3626, medic: 0x2a2018, sniper: 0x3a2818, spy: 0x2a1c14 }[cls] || 0x2a1c14;
