          ctx.fillStyle = '#f4efe4';
          ctx.beginPath();
          ctx.moveTo(mx - mw * 1.1, my - hgt * 0.15);
          ctx.quadraticCurveTo(mx, my + hgt * 0.9, mx + mw * 1.1, my - hgt * 0.15);
