        ctx.beginPath();
        for (let k = 0; k < 6; k++) ctx.lineTo(cx + Math.cos(k * PI / 3 + PI / 6) * r * 0.86, cy + Math.sin(k * PI / 3 + PI / 6) * r * 0.86);
        ctx.fill();
