    ctx.beginPath();
    ctx.arc(w * 0.33, h * 0.45, h * 0.06, 0, PI * 2);
    ctx.moveTo(w * 0.27, h * 0.45);
    ctx.lineTo(w * 0.39, h * 0.45);
    ctx.stroke();
