    ctx.textBaseline = 'middle';
    ctx.save();
    ctx.translate(w / 2, h / 2);
    ctx.rotate(-0.06);
    const s = fit(ctx, 'PREVIOUSLY', w * 0.86, Math.round(h * 0.4));
    ctx.font = `900 ${s}px ${FONT}`;
