    const grassAt = (z, x0, z0, x1, z1) => floor(G.b('grass#z'), ZONES[z][0] + x0, ZONES[z][2] + z0, ZONES[z][0] + x1, ZONES[z][2] + z1, 0.012, 0xffffff, 0.5);
