    block(none, p[0], p[1], p[2], 8.0, 4.7, 0.2, 0x1a1a1a);
    [-3.2, 3.2].forEach(dx => block(none, p[0] + dx, 0.6, p[2], 0.3, 1.2, 0.3, 0x2a2a2a));
    p = zp('ambush', -1.5, 1.4, -6);
