    p = zp('mush', 2.5, 1.5, -6);
    block(none, p[0], p[1], p[2], 4.5, 3, 1, 0xe2c82a);
    p = zp('mush', -1.6, 3.3, -6.4);
    panel(G.b('comic#zm'), p[0], p[1], p[2], 4.4, 3.4, 0);
    block(none, p[0], p[1], p[2] - 0.08, 4.6, 3.6, 0.1, 0x1a1a1a);
