    const hR = handOn(G, [-0.56, 0.08, 0.07], [0, -1, 0.15], [0, 0, -1], 'grip');
    const hL = handOn(G, [-0.36, 0.28, 0], [0.2, -0.6, 1], [0, -1, 0.2], 'grip');
