    const h = headPos(st);
    let camera;
    if (which === 'endA') camera = cam(V3.add(h, [0.32, -0.04, 0.48]), V3.add(h, [-0.04, -0.02, 0]), 30);
    else if (which === 'endB') camera = cam(V3.add(h, [0.05, -0.12, 0.95]), V3.add(h, [-0.28, -0.12, 0]), 38);
