    [40.875, 'touched'], [49.533, 'outsmart'], [65.767, 'battleA'], [68.722, 'flash'], [68.972, 'battleB'], [76.798, 'black'], [80.502, 'endA'],
    [81.127, 'endB'], [81.751, 'endC'], [82.375, 'logo'], [85.414, 'orange']
