  function debrisBurst(p, u, seed, n) {
    const g = rand(seed);
    const out = [];
    for (let i = 0; i < n; i++) out.push({ p, v: [(g() - 0.5) * 7, 3 + g() * 6, (g() - 0.5) * 7], u, s: 0.05 + g() * 0.12, seed: seed + i, grav: true });
    return out;
  }

