        if (u <= 0) return;
        const p = V3.add(d.p, V3.mul(d.v, u));
        if (d.grav) p[1] -= 4.9 * u * u;
        if (p[1] < -0.2) return;
        const g = rand(d.seed);
        const M = M4.chain(M4.translate(p[0], p[1], p[2]), M4.rotX(u * 7 + g() * 6), M4.rotZ(u * 5 + g() * 6), M4.scale(d.s * (1 + g()), d.s * (0.6 + g() * 0.6), d.s));
