      const FM = new Float32Array([x[0], x[1], x[2], 0, y[0], y[1], y[2], 0, z[0], z[1], z[2], 0, elbow[0], elbow[1], elbow[2], 1]);
      fx.draw(DP.fore, FM, { spec: [0.05, 5], rim: 0.85 });
