    [18, 10].forEach(x => [-1, 1].forEach(s => L.metal.at(x, 0.25, 18.0 + s * 0.9, h => { h.push(M4.rotZ(PI / 2)); h.prism(12, 0.35, 0.35, -0.12, 0.35, 0.35, 0.12, 0x2a2a2c, { capBottom: true }); h.pop(); })));
