    for (let i = 0; i <= 24; i++) {
      const a = (i / 24) * PI * 2;
      const r = 85 + 15 * S(a * 3) + 10 * C(a * 5);
      ring.push([S(a) * r, C(a) * r]);
    }
    b.push(M4.translate(0, -16, 0));
    cliffWall(b, ring, 22, 431, col, 4);
    b.pop();
    return b;
