        ctx.fillStyle = ['#cf9a5e', '#d8a868', '#c08a52', '#e0b476'][Math.floor(g() * 4)];
        ctx.beginPath();
        ctx.ellipse(x, y, rx, ry, a, 0, PI * 2);
        ctx.fill();
        ctx.fillStyle = 'rgba(255,240,200,0.4)';
