        b.quad(pts[0], pts[3], pts[2], pts[1], [pts[0], pts[3], pts[2], pts[1]].map(p => rgb(col ? col(p[0], p[2], p[1]) : 0xffffff)), [pts[0], pts[3], pts[2], pts[1]].map(p => [p[0] * uv, p[2] * uv]), [N(q[0][0], q[0][1]), N(q[3][0], q[3][1]), N(q[2][0], q[2][1]), N(q[1][0], q[1][1])]);
