      b.ellipsoid(w, hgt, w * 0.6, 14, 8, rgb([0xf6c0d8, 0xc8b8f0, 0xb8e0f4, 0xf8e4b0, 0xd0f0c0][i % 5]), { colorAt: p => ((Math.floor((p[1] + 40) / 6) % 2) ? [0xf6c0d8, 0xc8b8f0, 0xb8e0f4, 0xf8e4b0, 0xd0f0c0][i % 5] : 0xfff8fc) });
