    ribbonRoad(b, road, 0.9, 0xf4a4c0, 0.15);
    const road2 = curve(k => [lerp(40, -70, k) + C(k * 6) * 10, 0, lerp(20, 90, k)], 40).map(p => [p[0], valleyH(p[0], p[2]), p[2]]);
    ribbonRoad(b, road2, 0.7, 0x9ad0f4, 0.15);
