          q.at(-side * d / 2, h, 0, r => { r.push(M4.rotZ(side * 0.0)); r.box(1.2, 1.8, w + 0.4, [0x5c8ed8, 0xe87ea0, 0x9ad070][i % 3]); r.pop(); });
