    K.tube(b, curve(k => [-5.1, 0.5 - S(k * PI * 9) * 0.04, 6 + k * 29], 40), curve(() => 0.012, 40), 3, 0x4a3e34);
    [[-3, 9], [4, 14], [-6, 22], [6, 28], [2, 38]].forEach(([x, z], i) => b.at(x, 0.35, z, q => { q.push(M4.rotY(i)); q.prism(10, 0.3, 0.3, -0.35, 0.3, 0.3, 0.35, 0x2a2622, {}); q.pop(); }));
    return b;
