      ctx.strokeStyle = '#2a1810';
      ctx.lineWidth = W * 0.012;
      ctx.beginPath();
      ctx.moveTo(man + W * 0.045, H * 0.55);
      ctx.lineTo(lady - W * 0.035, H * 0.55);
