      [[man - W * 0.03, H * 0.95], [man + W * 0.03, H * 0.95], [lady - W * 0.02, H * 0.9], [lady + W * 0.02, H * 0.9]].forEach(([x, y]) => ctx.fillRect(x - W * 0.012, y - H * 0.1, W * 0.024, H * 0.1));
