    worried: { browInUp: 0.8, frown: 0.35, lidU: 0.6, wide: 0.2 },
    disgust: { sneer: 0.8, browDown: 0.5, frown: 0.4, lidU: 0.4, wide: 0.3 },
    shout: { browUp: 0.6, wide: 0.6, jaw: 0.9, round: 0.2, lidU: 0.9 }
