    return valley({
      shot: 'bluSoldier', camera: cam(V3.add(at, [1.6, 1.1, -2.6]), V3.add(at, [0, 1.1, 0]), 46), actors: [sol], scout: hit > 0 ? null : sc,
      booms: hit > 0 ? [{ p: V3.add(at, [0.6, 1.0, -0.7]), u: hit, s: 1.6, seed: 61 }] : [], set: 'valley'
    });
