    loft(b, [ring(-D.fore + 0.005, 0.044 * k, 0.047 * k, 0, col), ring(-0.16, 0.054 * k, 0.057 * k, 0, col), ring(0.0, 0.058 * k, 0.06 * k, 0, col)], 10, { capBottom: true });
    const cuff = P.jacket ? P.shirt : P.shirtOnly ? P.top : shade(col, 0.8);
