      K.tube(b, [[c[0] + s * R * 0.4, c[1] + R * 0.12, cz - R * 0.08], [ear[0] + s * R * 0.04, ear[1], ear[2] + R * 0.3], ear], [R * 0.02, R * 0.02, R * 0.02], 4, col);
