    b.push(M4.translate(0, 0, backZ), M4.rotX(-ch.recline));
    b.at(0, ch.top - 0.03, 0, h => h.box(ch.half * 2, 0.06, 0.05, Hi));
    b.at(0, ch.seatY + 0.08, -0.01, h => h.box(ch.half * 2, 0.05, 0.04, W));
    b.pop();
