      window: mesh(r, buildWindow),
      table: mesh(r, buildTable),
      food: mesh(r, buildFood),
      chairFrame: mesh(r, buildChairFrame),
      chairWeave: mesh(r, buildChairWeave),
      chairSeat: mesh(r, buildChairSeat),
