    this.categories = [
      ['autos', 'Авто и транспорт'],
      ['comedy', 'Комедия'],
      ['entertainment', 'Развлечения'],
      ['film', 'Кино и анимация'],
      ['games', 'Гаджеты и игры'],
      ['howto', 'Хобби'],
      ['music', 'Музыка'],
      ['news', 'Новости и блоги'],
      ['people', 'Люди'],
      ['pets', 'Питомцы и животные'],
      ['sports', 'Спорт'],
      ['travel', 'Путешествия и места']
    ];
